const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const LAN = 'http://192.168.3.201', PVE = 'https://192.168.3.200:8006';
const helpers = this.helpers;
const s = $getWorkflowStaticData('global');
const say = (text) => helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/sendMessage`, body: { chat_id: CHAT, text, disable_web_page_preview: true }, json: true, timeout: 15000 });
const get = (url, opts = {}) => helpers.httpRequest({ url, json: true, timeout: 20000, ...opts });
const safe = async (fn) => { try { return await fn(); } catch (e) { return null; } };
const lagosNow = () => new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const prom = async (expr) => { const r = await get(`${LAN}:9090/api/v1/query`, { qs: { query: expr } }); const v = r?.data?.result?.[0]?.value?.[1]; return v === undefined ? null : Number(v); };
const pveGet = (path) => get(`${PVE}/api2/json${path}`, { headers: { Authorization: `PVEAPIToken=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_ID}=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_SECRET}` }, skipSslCertificateValidation: true }).then(r => r.data);
const ghHeaders = (extra = {}) => ({ Authorization: `Bearer ${$env.HOMELAB_GITHUB_TOKEN || ''}`, Accept: 'application/vnd.github+json', 'User-Agent': 'homelab-n8n', ...extra });
const gh = (path, opts = {}) => { const { headers, ...rest } = opts; return helpers.httpRequest({ url: `https://api.github.com${path}`, json: true, timeout: 20000, headers: ghHeaders(headers), ...rest }); };
const REPO = $env.HOMELAB_GITHUB_REPO || 'theOGpython/homelab';

// Parse bank / token / data-purchase alert emails from Outlook into spending rows (for Google Sheets).
// Kuda alerts have a dedicated reader; other banks use the generic one. Edit the lists below to tune it.

// Regular payees → category (checked first). Examples: [/twins fresh fruits/i, 'Groceries'], [/landlord name/i, 'Rent']
const PAYEE_RULES = [
];
const SENDERS = /kuda|gtbank|gtco|access|zenith|uba|firstbank|first bank|opay|moniepoint|palmpay|wema|alat|sterling|fcmb|stanbic|fidelity|union|ecobank|polaris|providus|ekedc|ekoelectric|eko electricity|ikedc|airtel|mtn|glo|9mobile|paystack|flutterwave|chowdeck|bolt|uber/i;
const SUBJECT = /debit|credit|transaction|alert|receipt|token|payment|purchase|transfer|recharge|subscription|just sent|just spent|just paid/i;
const CATEGORIES = [
  ['Power', /ekedc|eko electric|ikedc|prepaid|electricity|disco|\btoken\b/i],
  ['Data & airtime', /airtel|\bmtn\b|\bglo\b|9mobile|\bdata\b|airtime|recharge/i],
  ['Groceries', /\beggs?\b|fruit|vegetable|\bveg\b|market|foodstuff|supermarket|shoprite|\bspar\b|grocer|provision|\brice\b|bread|\bmeat\b|\bfish\b|yam|garri/i],
  ['Health', /pharmac|hospital|clinic|medic|\bdrugs?\b|\blab\b|dental|optical|health/i],
  ['Food', /chowdeck|glovo|jumia food|restaurant|kfc|chicken republic|domino|eatery|\bcafe|suya|shawarma|\blunch\b|dinner|\bfood\b/i],
  ['Transport', /uber|\bbolt\b|indrive|rida|\bfuel\b|petrol|filling station|\btoll\b|\bcab\b|transport/i],
  ['Subscriptions', /netflix|spotify|apple|google|youtube|showmax|dstv|gotv|icloud|anthropic|openai|github|microsoft/i],
  ['Cash', /\batm\b|withdrawal|\bpos\b/i],
];
const num = (v) => Number(String(v).replace(/,/g, ''));
const MONEY = String.raw`(?:NGN|N|₦)\s?([\d,]+(?:\.\d{1,2})?)`;
const decode = (h) => String(h || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|h\d)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&#8358;|&#x20a6;/gi, '₦').replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&').replace(/&#39;|&rsquo;|&apos;/gi, "'").replace(/&quot;/gi, '"')
  .replace(/[ \t]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();

// ---- Kuda: "You just sent ₦X to PAYEE - [branch -] NOTE." / "NAME just sent you ₦X." / "You just spent|paid ₦X at|for MERCHANT." ----
function parseKuda(text) {
  const t = text.replace(/\n/g, ' ').replace(/^.*?Transaction Notification\s*/i, '');   // drop the logo/heading before the message
  const END = String.raw`\.\s*(?:Love\b|Need to know|$)`;
  let m;
  if ((m = t.match(new RegExp(String.raw`You just sent\s*₦\s?([\d,]+(?:\.\d{1,2})?)\s+to\s+(.+?)` + END, 'i')))) {
    const parts = m[2].split(/\s+-\s+/).map(x => x.trim()).filter(Boolean);
    return { type: 'debit', amount: num(m[1]), party: parts[0], note: parts.length > 1 ? parts[parts.length - 1] : '', dir: 'To' };
  }
  if ((m = t.match(/(?:^|,\s*)([^,.₦]{2,80}?)\s+just sent you\s*₦\s?([\d,]+(?:\.\d{1,2})?)/i))) {
    return { type: 'credit', amount: num(m[2]), party: m[1].trim(), note: '', dir: 'From' };
  }
  if ((m = t.match(new RegExp(String.raw`You just (?:spent|paid)\s*₦\s?([\d,]+(?:\.\d{1,2})?)\s+(?:at|to|for|on)\s+(.+?)` + END, 'i')))) {
    const parts = m[2].split(/\s+-\s+/).map(x => x.trim()).filter(Boolean);
    return { type: 'debit', amount: num(m[1]), party: parts[0], note: parts.length > 1 ? parts[parts.length - 1] : '', dir: 'At' };
  }
  if ((m = t.match(new RegExp(String.raw`You just (?:bought|purchased|recharged)\s+(?:₦\s?([\d,]+(?:\.\d{1,2})?)\s+)?(.+?)(?:\s+(?:worth)\s+₦\s?([\d,]+(?:\.\d{1,2})?))?` + END, 'i')))) {
    const amt = m[1] || m[3];
    if (amt) return { type: 'debit', amount: num(amt), party: m[2].trim(), note: '', dir: 'Bought' };
  }
  return null;
}

// ---- Generic reader for other banks ----
function parseGeneric(subject, body) {
  const text = `${subject}\n${body}`;
  const labelled = text.match(new RegExp(String.raw`(?:amount|amt|debited|credited|value|total|paid)[^\d₦N]{0,20}` + MONEY, 'i'));
  const anyMoney = text.match(new RegExp(MONEY, 'i'));
  const amount = labelled ? num(labelled[1]) : anyMoney ? num(anyMoney[1]) : null;
  if (!amount) return null;
  const CREDIT = /\bcredit(ed)?\b|\bcr\b|received|deposit|inflow/i, DEBIT = /\bdebit(ed)?\b|\bdr\b|purchase|paid|payment|token|recharge|withdrawal|sent/i;
  const type = DEBIT.test(subject) ? 'debit' : CREDIT.test(subject) ? 'credit' : CREDIT.test(body.slice(0, 200)) ? 'credit' : DEBIT.test(text) ? 'debit' : 'unknown';
  const note = (text.match(/(?:description|desc|narration|details|remarks|merchant)\s*[:\-]\s*([^\n]{3,80})/i)?.[1] || subject).trim();
  const balance = text.match(new RegExp(String.raw`(?:avail(?:able)?\s*bal(?:ance)?|bal(?:ance)?)\s*[:\-]?\s*` + MONEY, 'i'));
  return { type, amount, party: '', note, balance: balance ? num(balance[1]) : '' };
}

const rows = [];
for (const item of $input.all()) {
  const m = item.json;
  const fromName = m.from?.emailAddress?.name || m.sender?.emailAddress?.name || '';
  const fromAddr = m.from?.emailAddress?.address || m.sender?.emailAddress?.address || '';
  const subject = m.subject || '';
  const body = decode(m.body?.content || m.bodyPreview || '');
  if (!SENDERS.test(`${fromName} ${fromAddr} ${subject}`) || !SUBJECT.test(`${subject} ${body.slice(0, 400)}`)) continue;

  const isKuda = /kuda/i.test(`${fromName} ${fromAddr}`);
  const p = (isKuda && parseKuda(body)) || parseGeneric(subject, body);
  if (!p || !p.amount) continue;

  const description = (p.party ? `${p.dir ? p.dir + ' ' : ''}${p.party}${p.note ? ' · ' + p.note : ''}` : p.note || subject).slice(0, 100);
  const hay = `${p.note} ${p.party}`;
  const category = p.type === 'credit' ? 'Income'
    : (PAYEE_RULES.find(([re]) => re.test(hay)) || [])[1]
      || (CATEGORIES.find(([, re]) => re.test(hay)) || [])[0]
      || (CATEGORIES.find(([, re]) => re.test(`${subject} ${fromName}`)) || [])[0]
      || (p.party && isKuda && p.dir === 'To' ? 'Transfers' : 'Other');
  const when = new Date(m.receivedDateTime || Date.now());
  rows.push({ json: {
    Date: when.toLocaleString('en-GB', { timeZone: 'Africa/Lagos' }), Month: when.toISOString().slice(0, 7),
    Type: p.type, Amount: p.amount, Category: category, Description: description, Balance: p.balance ?? '',
    Source: (fromName || fromAddr).slice(0, 40), EmailId: m.id || '',
  } });
}
return rows;

const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const LAN = 'http://192.168.3.201', PVE = 'https://192.168.3.200:8006';
const helpers = this.helpers;
const s = $getWorkflowStaticData('global');
const say = (text) => helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/sendMessage`, body: { chat_id: CHAT, text, disable_web_page_preview: true }, json: true, timeout: 15000 });
const get = (url, opts = {}) => helpers.httpRequest({ url, json: true, timeout: 20000, ...opts });
const safe = async (fn) => { try { return await fn(); } catch (e) { return null; } };
const lagosNow = () => new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const prom = async (expr) => { const r = await get(`${LAN}:9090/api/v1/query`, { qs: { query: expr } }); const v = r?.data?.result?.[0]?.value?.[1]; return v === undefined ? null : Number(v); };
const pveGet = (path) => get(`${PVE}/api2/json${path}`, { headers: { Authorization: `PVEAPIToken=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_ID}=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_SECRET}` }, skipSslCertificateValidation: true }).then(r => r.data);
const ghHeaders = (extra = {}) => ({ Authorization: `Bearer ${$env.HOMELAB_GITHUB_TOKEN || ''}`, Accept: 'application/vnd.github+json', 'User-Agent': 'homelab-n8n', ...extra });
const gh = (path, opts = {}) => { const { headers, ...rest } = opts; return helpers.httpRequest({ url: `https://api.github.com${path}`, json: true, timeout: 20000, headers: ghHeaders(headers), ...rest }); };
const REPO = $env.HOMELAB_GITHUB_REPO || 'theOGpython/homelab';

// Monthly spending summary from the Google Sheet rows (runs on the 1st for last month).
const now = lagosNow();
const prev = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const month = `${prev.getFullYear()}-${pad(prev.getMonth() + 1)}`;
const rows = $input.all().map(i => i.json).filter(r => r.Month === month);
const naira = (n) => '₦' + Math.round(n).toLocaleString('en-NG');
if (!rows.length) { await say(`💳 No transactions recorded for ${month}.`); return [{ json: { sent: true } }]; }
const debits = rows.filter(r => r.Type === 'debit'), credits = rows.filter(r => r.Type === 'credit');
const sum = (a) => a.reduce((t, r) => t + Number(r.Amount || 0), 0);
const byCat = {};
for (const r of debits) byCat[r.Category || 'Other'] = (byCat[r.Category || 'Other'] || 0) + Number(r.Amount || 0);
const top = Object.entries(byCat).sort((a, b) => b[1] - a[1]);
const biggest = [...debits].sort((a, b) => b.Amount - a.Amount).slice(0, 3);
const label = prev.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
const L = [`💳 Spending in ${label}`, `   Out: ${naira(sum(debits))} (${debits.length} transactions)`, `   In: ${naira(sum(credits))}`, '', '📊 By category:'];
for (const [c, v] of top) L.push(`   ${c}: ${naira(v)} (${Math.round(v / sum(debits) * 100)}%)`);
L.push('', '🔝 Biggest:'); for (const r of biggest) L.push(`   ${naira(r.Amount)}: ${r.Description}`);
await say(L.join('\n'));
return [{ json: { sent: true } }];
